import { NavLink } from 'react-router-dom';

const menuItems = [
  { label: 'Dashboard', path: '/dashboard' },
  { label: 'Nhân viên', path: '/employees' },
  { label: 'Phòng ban', path: '/departments' },
  { label: 'Chấm công', path: '/attendance' },
  { label: 'Nghỉ phép', path: '/leave' },
  { label: 'Hồ sơ cá nhân', path: '/profile' },
  { label: 'Giới thiệu nhóm', path: '/about-team' },
];

function Sidebar() {
  return (
    <div style={{
      width: '200px',
      minHeight: '100vh',
      backgroundColor: '#f8f9fa',
      borderRight: '1px solid #ddd',
      paddingTop: '16px'
    }}>
      <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
        {menuItems.map((item) => (
          <li key={item.path}>
            <NavLink
              to={item.path}
              style={({ isActive }) => ({
                display: 'block',
                padding: '10px 20px',
                textDecoration: 'none',
                fontSize: '14px',
                color: isActive ? '#2563eb' : '#444',
                backgroundColor: isActive ? '#e8f0fe' : 'transparent',
                borderLeft: isActive ? '3px solid #2563eb' : '3px solid transparent',
                fontWeight: isActive ? '600' : 'normal'
              })}
            >
              {item.label}
            </NavLink>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Sidebar;
